private Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType, Type genericType) {
    for (Type bound : typeVariable.getBounds()) {
        if (bound instanceof Class) {
            return (Class<?>) bound;
        } else if (bound instanceof ParameterizedType) {
            return resolveRawClass(bound, targetType);
        }
    }
    return Object.class;
}

private Class<?> resolveRawClass(Type type, Map<TypeVariable<?>, Class<?>> typeVariableMap) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        return parameterizedType.getRawType();
    } else if (type instanceof GenericArrayType) {
        GenericArrayType genericArrayType = (GenericArrayType) type;
        Type componentType = genericArrayType.getGenericComponentType();
        return Array.newInstance(resolveRawClass(componentType, typeVariableMap), 0).getClass();
    } else if (type instanceof TypeVariable) {
        return typeVariableMap.get(type);
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] upperBounds = wildcardType.getUpperBounds();
        return (upperBounds.length > 0) ? resolveRawClass(upperBounds[0], typeVariableMap) : Object.class;
    } else if (type instanceof IntersectionType) {
        IntersectionType intersectionType = (IntersectionType) type;
        Type[] bounds = intersectionType.getBounds();
        return (bounds.length > 0) ? resolveRawClass(bounds[0], typeVariableMap) : Object.class;
    } else {
        return Object.class;
    }
}

